SELECT 
FROM project
WHERE project_id = #{projectId}

SELECT 
FROM project
WHERE serial_number = #{serialNumber}

SELECT p.id, p.project_id, p.serial_number, p.title, p.description, p.category_id, p.tags, p.requirements, p.skill_level, p.team_size_min, p.team_size_max, p.duration_days, p.budget_type, p.budget_amount, p.currency, p.published_at, p.submitted_at, p.application_deadline, p.expected_start_date, p.expected_end_date, p.status, p.reject_reason, p.progress, p.publisher_id, p.accepted_team_id, p.application_count, p.view_count, p.favorite_count, p.create_time, p.update_time, p.version, u.nickname AS publisher_name FROM project p LEFT JOIN user u ON p.publisher_id = u.user_id
p.status = #{status}
ORDER BY p.create_time DESC LIMIT #{offset}, #{limit}

SELECT 
FROM project
WHERE publisher_id = #{publisherId}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT FROM project WHERE status = 'published'
AND (
JSON_CONTAINS(tags, JSON_QUOTE(#{tag}))
)
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM project
WHERE project_id = #{projectId}

SELECT COUNT(1)
FROM project
WHERE serial_number = #{serialNumber}

SELECT 
FROM project
WHERE publisher_id = #{publisherId} AND status = #{status}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM project
WHERE status = #{status}
  AND update_time <= #{updateTimeBefore}
ORDER BY update_time ASC

SELECT 
FROM project
WHERE status = 'published' AND category_id = #{categoryId}
ORDER BY published_at DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM project
WHERE status = 'published'

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND category_id = #{categoryId}


    AND skill_level = #{skillLevel}


    AND budget_amount >= #{budgetMin}


    AND budget_amount <= #{budgetMax}

ORDER BY published_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM project
WHERE status = 'published'

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND category_id = #{categoryId}


    AND skill_level = #{skillLevel}


    AND budget_amount >= #{budgetMin}


    AND budget_amount <= #{budgetMax}

SELECT 
FROM project
WHERE accepted_team_id = #{teamId}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM project
WHERE accepted_team_id = #{teamId} AND status = #{status}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}
